# Logo incorporada para não depender de um arquivo adicional no deploy.
LOGO = ""
st.markdown(f'<header class="brand-header"><img src="data:image/png;base64,{LOGO}" alt="HOMEM.COM"><p>LOCALIZADOR DE TECIDOS</p></header>', unsafe_allow_html=True)
if "navigation" not in st.session_state:
    st.session_state["navigation"] = "Buscar"


def change_page(destination):
    close_details()
    st.session_state.pop("pending_replacement", None)
    st.session_state["navigation"] = destination


with st.container(key="navigation_buttons"):
    columns = st.columns(3, gap="small")
    for column, destination in zip(columns, ["Buscar", "Cadastrar", "Cadastros"]):
        with column:
            st.button(destination, key=f"nav_{destination}",
                type="primary" if st.session_state["navigation"] == destination else "secondary",
                use_container_width=True, on_click=change_page, args=(destination,))
page = st.session_state["navigation"]
if page != "Cadastrar":
    st.caption("Dados atualizados automaticamente a cada 30 segundos.")


@st.fragment(run_every="30s" if page != "Cadastrar" and not st.session_state.get("details") else None)
def render_page():
    try:
        sheet = connect()
        records = read_rows(sheet)
    except (KeyError, FileNotFoundError):
        st.info("Configure a conexão com o Google Sheets para começar. Siga o README.md e o modelo .streamlit/secrets.toml.example.")
        st.stop()
    except Exception as error:
        st.error(f"Não foi possível carregar os dados ({type(error).__name__}). Confira a configuração, o compartilhamento e os cabeçalhos da aba.")
        if isinstance(error, ValueError):
            st.warning(str(error))
        st.stop()

    if "release_success" in st.session_state:
        st.success(st.session_state.pop("release_success"))

    if page == "Buscar":
        st.title("Onde está o tecido?")
        st.caption("Digite a referência completa para encontrar suas localizações.")
        with st.form("search_form", clear_on_submit=True):
            typed_query = st.text_input("Referência do tecido", placeholder="Ex.: 10331", key="search_input")
            submitted = st.form_submit_button("Buscar tecido", type="primary", use_container_width=True)
        if submitted:
            query = typed_query.strip()
            if query:
                matches = [r for r in records if query.casefold() == r["Referencia"].casefold()]
                if matches:
                    open_details(query=query)
                else:
                    st.warning(f"Referência {query} não encontrada. Confira o código completo.")
            else:
                st.info("Digite a referência completa para buscar.")
        st.caption("Toque em Buscar tecido para ver as localizações.")

    elif page == "Cadastrar":
        clear_saved_registration()
        st.title("Cadastrar localização")
        st.caption("Cada divisão guarda uma referência. A mesma referência pode ocupar várias divisões. Se o destino estiver ocupado, você poderá confirmar a substituição.")
        reference = st.text_input("Referência do tecido", placeholder="Ex.: 10331", key="new_reference")
        shelf = st.text_input("Prateleira", placeholder="Ex.: p1", key="new_shelf")
        division = st.text_input("Divisão", placeholder="Ex.: a1", key="new_division")
        st.caption("P1 e P2: A1–A4 ou B1–B4. P3 a P14: A1–A5 ou B1–B5.")
        draft = ("Cadastrar", reference.strip(), shelf.strip().upper(), division.strip().upper())
        pending = st.session_state.get("pending_replacement")
        if pending and pending["draft"] != draft:
            st.session_state.pop("pending_replacement", None)
            pending = None
        if st.button("Salvar cadastro", type="primary", use_container_width=True,
            disabled=pending is not None):
            try:
                row = validate(reference, shelf, division)
                values = sheet.get_all_values()
                plan = plan_save(values, row)
                if plan["replaced"]:
                    st.session_state["pending_replacement"] = {
                        "draft": draft, "values": values, "plan": plan,
                    }
                    st.rerun()
                else:
                    apply_plan(sheet, plan)
                    st.rerun()
            except Exception as error:
                show_save_error(error)
        if "saved_location" in st.session_state:
            st.success(st.session_state.pop("saved_location"))

    elif page == "Cadastros":
        st.title("Consultar cadastros")
        selected = st.selectbox("Filtrar por prateleira", ["Todas"] + SHELVES)
        visible = [r for r in records if selected == "Todas" or r["Prateleira"] == selected]
        st.caption(f"{len(visible)} localização(ões) cadastrada(s)")
        if not visible:
            st.info("Nenhuma referência cadastrada nesta seleção.")
        for index, record in enumerate(visible):
            location_card(record)
            if st.button("Ver localização", key=f"details_list_{index}", use_container_width=True):
                open_details(record=record)
        output = io.StringIO()
        writer = csv.DictWriter(output, fieldnames=HEADERS)
        writer.writeheader()
        writer.writerows(records)
        st.download_button("Baixar cadastro completo (CSV)", output.getvalue().encode("utf-8-sig"), "referencias_tecidos.csv", "text/csv")



render_page()
if page == "Cadastrar" and st.session_state.get("pending_replacement"):
    confirm_replacement()
elif st.session_state.get("details"):
    show_details()

